/**
 * Searches the master NASM RAG library by keywords, goal, or OPT™ phase.
 */
export function queryNasmRagLibrary(query: {
  keyword?: string
  goal?: 'fat_loss' | 'hypertrophy' | 'performance' | 'assessment' | 'nutrition' | 'coaching' | 'corrective' | 'sports_performance' | 'behavior_change' | 'mma' | 'golf' | 'home_gym' | 'social_media' | 'glp1' | 'cardio' | 'meal_prep' | 'podcasting' | 'physique' | 'weight_loss'
  nasmOptPhase?: number
}): RagDocumentMetadata[] {
  return NASM_RAG_LIBRARY.filter(doc => {
    if (query.nasmOptPhase) {
      if (Array.isArray(doc.nasmOptPhase)) {
        if (!doc.nasmOptPhase.includes(query.nasmOptPhase)) return false
      } else if (doc.nasmOptPhase !== query.nasmOptPhase && doc.category === 'Workout Template') {
        return false
      }
    }

    if (query.goal) {
      if (query.goal === 'fat_loss' && doc.goalCategory !== 'Fat Loss / Stabilization' && doc.category === 'Workout Template') return false
      if (query.goal === 'hypertrophy' && doc.goalCategory !== 'Hypertrophy / Muscular Development' && doc.category === 'Workout Template') return false
      if (query.goal === 'performance' && doc.goalCategory !== 'Maximal Strength & Athletic Performance' && doc.category === 'Workout Template') return false
      if (query.goal === 'assessment' && doc.category !== 'Clinical Assessment') return false
      if ((query.goal === 'nutrition' || query.goal === 'coaching') && doc.category !== 'Nutrition & Coaching Protocol') return false
      if (query.goal === 'corrective' && doc.category !== 'Corrective Exercise Protocol') return false
      if (query.goal === 'sports_performance' && doc.category !== 'Sports Performance Protocol') return false
      if (query.goal === 'behavior_change' && doc.category !== 'Behavior Change Protocol') return false
      if (query.goal === 'mma' && doc.category !== 'MMA Conditioning Protocol') return false
      if (query.goal === 'golf' && doc.category !== 'Golf Fitness Protocol') return false
      if (query.goal === 'home_gym' && doc.category !== 'Facility & Equipment Design') return false
      if (query.goal === 'social_media' && doc.category !== 'Social Media & Digital Strategy') return false
      if (query.goal === 'glp1' && doc.category !== 'Pharmacology & Weight Loss Protocol') return false
      if (query.goal === 'cardio' && doc.category !== 'Advanced Cardio Protocol') return false
      if (query.goal === 'meal_prep' && doc.category !== 'Bodybuilding & Meal Prep Protocol') return false
      if (query.goal === 'podcasting' && doc.category !== 'Podcasting & Media Production') return false
      if (query.goal === 'physique' && doc.category !== 'Physique & Bodybuilding Protocol') return false
      if (query.goal === 'weight_loss' && doc.category !== 'Weight Loss & Metabolic Specialization') return false
    }

    if (query.keyword) {
      const q = query.keyword.toLowerCase()
      const matchesTitle = doc.title.toLowerCase().includes(q)
      const matchesSummary = doc.summary.toLowerCase().includes(q)
      const matchesConcepts = doc.keyConcepts.some(c => c.toLowerCase().includes(q))
      if (!matchesTitle && !matchesSummary && !matchesConcepts) return false
    }

    return true
  })
}
